void QThreadData::clearEvents()
{
    // The events must be deleted without holding the mutex: their destructors
    // may post new events (e.g. by calling deleteLater()), which locks it again.
    // Those newly posted events are discarded too, so loop until nothing is left.
    QVarLengthArray<QEvent *> events;
    for (;;) {
        {
            const auto locker = qt_scoped_lock(postEventList.mutex);
            for (const QPostEvent &pe : std::as_const(postEventList)) {
                if (pe.event) {
                    pe.receiver->d_func()->postedEvents.fetchAndSubAcquire(1);
                    pe.event->m_posted = false;
                    events.append(pe.event);
                }
            }
            postEventList.clear();
            // we may be called from within sendPostedEvents()
            postEventList.startOffset = 0;
            postEventList.insertionOffset = 0;
        }
        if (events.isEmpty())
            break;
        qDeleteAll(events);
        events.clear();
    }
}

